CHUNKS = [
    {"id": "a", "vec": [1.0, 0.0], "tokens": 400},
    {"id": "b", "vec": [0.8, 0.6], "tokens": 500},
    {"id": "c", "vec": [0.6, 0.8], "tokens": 300},
