]
QUERY = [1.0, 0.0]

def test_fits_all():
    assert solution.select_context(QUERY, CHUNKS, 4, 1400) == ["a", "b", "c", "d"]

def test_skips_large():
    assert solution.select_context(QUERY, CHUNKS, 4, 700) == ["a", "c"]

def test_respects_k():
    assert solution.select_context(QUERY, CHUNKS, 2, 1400) == ["a", "b"]

def test_zero_budget():
    assert solution.select_context(QUERY, CHUNKS, 4, 0) == []

def test_negative_budget():
    try:
        solution.select_context(QUERY, CHUNKS, 4, -1)
    except ValueError:
        return
    raise AssertionError("expected ValueError")

def test_keeps_rank_order():
    assert solution.select_context(QUERY, CHUNKS, 3, 1000) == ["a", "b"]
